const input = $input.first().json;
const d = input.body || input;
const run = d.run || { runId: 'unknown', mode: 'manual', dryRun: false };
if (run.dryRun && run.forceFailAt === 'agent5') throw new Error('Forced test failure in Agent 5 (dry run, on purpose)');
console.log('Agent 5: run', run.runId, run.dryRun ? '(DRY RUN)' : '', '| mode:', run.mode);
return [{ json: { finalPost: d.finalPost || '', topic: d.topic, style: d.style, length: d.length, run,
  sources: (Array.isArray(d.sources) ? d.sources : []).filter(s => s && /^https?:\/\/[^\s]+$/.test(s.url || '') && s.url.length < 1500 && !/^https?:\/\/(www\.)?google\.[a-z.]+\/(goto|url)\b/.test(s.url)),
  kind: d.kind || 'post', slugOverride: d.slugOverride || '', appendSources: d.appendSources !== false, tags: d.tags || null,
  editorNote: d.editorNote || '', writer: d.writer || null, researchSummary: String(d.researchSummary || ''),
  targetWords: Number(d.targetWords) || null, editorOk: (d.kind || 'post') === 'digest' ? true : d.editorOk === true } }];

// Deterministic guard: models never add links. Any markdown link whose URL is not in the research sources loses its link.
const d = $input.first().json;
const strip = (u) => String(u).replace(/\/$/, '');
const allowed = new Set(d.sources.map(s => strip(s.url)));
let md = d.finalPost, removed = 0, citations = 0;
md = md.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (m, t, u) => allowed.has(strip(u)) ? m : (removed++, t));
// Inline citations like "(Source 1)", "(Sources 1 and 3)" or "[2]" do not match the unnumbered Sources list: remove them.
md = md.replace(/\s?\((?:see\s+)?sources?\s*\d+(?:\s*(?:,|and|&|\/)\s*\d+)*\)/gi, () => (citations++, ''))
       .replace(/\s?\[(\d{1,2})\](?!\()/g, () => (citations++, ''));
md = md.replace(/\n#{1,3}\s*(Sources|References|Further reading|Citations)\s*\n[\s\S]*$/i, '\n').trim();
if (d.appendSources && d.sources.length)
  md += '\n\n## Sources\n\n' + d.sources.map(s => `- [${String(s.title || s.url).replace(/[\[\]]/g, '').slice(0, 200)}](${s.url})`).join('\n');
console.log('Agent 5: links removed by guard:', removed, '| inline citations removed:', citations);
const wordCount = (md.match(/\S+/g) || []).length;
return [{ json: { ...d, finalPost: md, linksRemoved: removed, citationsRemoved: citations, wordCount, sectionCount: (md.match(/^##\s+/gm) || []).length } }];

// Quality checks. Issues lower the score; BLOCKERS stop the publish (the post is held and the error workflow alerts the owner).
const d = $input.first().json;
const p = d.finalPost, issues = [];
const isDigest = d.kind === 'digest';
// Minimum length is a flat floor, not a share of the writer's target (2026-11-13): the Opus editor cuts padding and
// unsupported claims on purpose, and the writer stops when the research runs out, so a true post is often well under
// the target (run-20261113-130000-2tmp: target 1600, edited post 843 words, held at "below 960"). Short and true is fine.
const min = isDigest ? 80 : 400;
const body = p.replace(/\n## Sources\n[\s\S]*$/, '');                 // the Sources list is generated, not written
const prose = body.replace(/```[\s\S]*?```/g, ' ').replace(/`[^`]*`/g, ' ').replace(/\]\([^)]*\)/g, ']');
const unquoted = prose.replace(/"[^"\n]*"|“[^”\n]*”/g, ' ');
if (d.wordCount < min) issues.push({ type: 'word_count_low', severity: 'critical', message: `Word count ${d.wordCount} below ${min}` });
if (!/^#\s+/.test(p)) issues.push({ type: 'missing_title', severity: 'critical', message: 'Missing H1 title' });
if (!isDigest && d.sectionCount < 3) issues.push({ type: 'insufficient_sections', severity: 'medium', message: `Only ${d.sectionCount} sections` });
if (!d.editorOk) issues.push({ type: 'editor_incomplete', severity: 'critical', message: 'The editor did not check every section: ' + String(d.editorNote).slice(0, 120) });
// Script check: CJK, Cyrillic, Arabic, Hebrew, Thai, Hangul (qwq sometimes slips into Chinese).
const foreign = (prose.match(/[Ѐ-ӿ֐-׿؀-ۿ฀-๿぀-ヿ㐀-䶿一-鿿가-힯]+/g) || []);
if (foreign.length) issues.push({ type: 'non_latin_script', severity: 'critical', message: 'Text in another script: ' + foreign.slice(0, 3).join(' ') });
// First person, outside quotes and code.
const fp = (unquoted.match(/\b(?:[Ww]e|[Ww]e're|[Ww]e've|[Ww]e'll|[Ww]e'd|[Oo]ur|[Oo]urs|[Oo]urselves|I|I'm|I've|I'll|I'd|my|me)\b(?![\/-])/g) || []);
if (fp.length) issues.push({ type: 'first_person_language', severity: 'high', message: `First person outside quotes (${fp.length}x: ${[...new Set(fp)].slice(0, 4).join(', ')})` });
// Numbers must come from the research: every number with 2+ digits or a decimal point must appear in the research, topic or source titles.
const R = (String(d.researchSummary) + ' ' + String(d.topic) + ' ' + d.sources.map(s => s.title + ' ' + s.url).join(' ')).replace(/,/g, '');
const nums = [...new Set((prose.match(/(?<![\w.])\d[\d,]*(?:\.\d+)*/g) || []).map(x => x.replace(/,/g, '')))];
const esc = (x) => x.replace(/\./g, '\\.');
const unsupported = nums.filter(x => (x.includes('.') || Number(x) > 10) && !new RegExp('(^|[^\\d.])' + esc(x) + '(?![\\d]|\\.\\d)').test(R));
if (unsupported.length) issues.push({ type: 'unsupported_numbers', severity: 'critical', message: 'Numbers not in the research: ' + unsupported.slice(0, 8).join(', ') });
if (d.linksRemoved > 0) issues.push({ type: 'unlisted_links_removed', severity: 'medium', message: `${d.linksRemoved} links not in the research were removed` });
if (d.citationsRemoved > 0) issues.push({ type: 'inline_citations_removed', severity: 'medium', message: `${d.citationsRemoved} inline citations removed` });
let score = 10 - issues.reduce((s, i) => s + ({ critical: 3, high: 2, medium: 1 }[i.severity] || 0), 0);
score = Math.max(0, score);
const MIN_SCORE = 6;
const blockers = issues.filter(i => i.severity === 'critical').map(i => i.message);
if (score < MIN_SCORE && !blockers.length) blockers.push(`quality score ${score} below ${MIN_SCORE}`);
console.log('Agent 5: quality score', score, '| issues', JSON.stringify(issues.map(i => i.type)), '| blockers', JSON.stringify(blockers));
return [{ json: { ...d, quality_score: score, issues, blockers, wouldPublish: blockers.length === 0, hasIssues: issues.length > 0, timestamp: new Date().toISOString() } }];

// Markdown -> HTML (block-aware: lists, quotes and code stay grouped; underscores inside URLs are left alone).
const d = $input.first().json;
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
function inline(s) {
  const keep = [];
  s = esc(s);
  s = s.replace(/`([^`]+)`/g, (m, c) => { keep.push(`<code>${c}</code>`); return `\u0000${keep.length - 1}\u0000`; });
  s = s.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (m, t, u) => { keep.push(`<a href="${u.replace(/"/g, '%22')}" target="_blank" rel="noopener noreferrer">${t}</a>`); return `\u0000${keep.length - 1}\u0000`; });
  s = s.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>').replace(/(^|[^\w*])\*(?!\s)(.+?)\*(?!\w)/g, '$1<em>$2</em>')
       .replace(/(^|\W)_(?!\s)(.+?)_(?!\w)/g, '$1<em>$2</em>');
  return s.replace(/\u0000(\d+)\u0000/g, (m, i) => keep[Number(i)]);
}
function toHtml(md) {
  const lines = md.split('\n'), out = []; let i = 0, para = [];
  const flush = () => { if (para.length) { out.push('<p>' + inline(para.join(' ')) + '</p>'); para = []; } };
  while (i < lines.length) {
    const l = lines[i];
    if (/^```/.test(l)) { flush(); const buf = []; i++; while (i < lines.length && !/^```/.test(lines[i])) buf.push(lines[i++]); i++; out.push('<pre><code>' + esc(buf.join('\n')) + '</code></pre>'); continue; }
    let m;
    if ((m = l.match(/^(#{1,4})\s+(.*)$/))) { flush(); const lv = Math.max(2, m[1].length); out.push(`<h${lv}>${inline(m[2].trim())}</h${lv}>`); i++; continue; }
    if (/^\s*[-*]\s+/.test(l)) { flush(); const it = []; while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) it.push('<li>' + inline(lines[i++].replace(/^\s*[-*]\s+/, '')) + '</li>'); out.push('<ul>' + it.join('') + '</ul>'); continue; }
    if (/^\s*\d+[.)]\s+/.test(l)) { flush(); const it = []; while (i < lines.length && /^\s*\d+[.)]\s+/.test(lines[i])) it.push('<li>' + inline(lines[i++].replace(/^\s*\d+[.)]\s+/, '')) + '</li>'); out.push('<ol>' + it.join('') + '</ol>'); continue; }
    if (/^>\s?/.test(l)) { flush(); const q = []; while (i < lines.length && /^>\s?/.test(lines[i])) q.push(lines[i++].replace(/^>\s?/, '')); out.push('<blockquote>' + inline(q.join(' ')) + '</blockquote>'); continue; }
    if (/^(-{3,}|\*{3,})\s*$/.test(l)) { flush(); out.push('<hr>'); i++; continue; }
    if (!l.trim()) { flush(); i++; continue; }
    para.push(l.trim()); i++;
  }
  flush(); return out.join('\n');
}
const tm = d.finalPost.match(/^#\s+(.+)$/m);
const title = (tm ? tm[1] : d.topic || 'Untitled').replace(/[*_`#]/g, '').trim().slice(0, 300);
const bodyMd = tm ? d.finalPost.replace(tm[0], '').trim() : d.finalPost;       // the site renders the title itself
const content = toHtml(bodyMd);
let slug = d.slugOverride || title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
if (slug.length > 80) slug = slug.slice(0, 80).replace(/-[^-]*$/, '');
if (!slug) slug = 'post-' + Date.now();
const today = $now.setZone('UTC').toISODate();
if (!d.slugOverride) {        // never overwrite an existing post (the API upserts by slug)
  const res = await this.helpers.httpRequest({ url: `https://your-blog.example/api/blog/posts/${slug}`, json: true, timeout: 15000, returnFullResponse: true, ignoreHttpStatusErrors: true });
  if (res.statusCode === 200) slug = `${slug}-${today}`;
  else if (res.statusCode !== 404) throw new Error('Could not check whether the slug is free: HTTP ' + res.statusCode);
}
const firstP = (content.match(/<p>([\s\S]*?)<\/p>/) || [, ''])[1].replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');
const excerpt = firstP.length <= 160 ? firstP : firstP.slice(0, 157).replace(/\s+\S*$/, '') + '...';
const KW = { 'AI': /\b(ai|llm|model|machine learning|neural|gpt|agent)\b/i, 'Security': /\b(security|vulnerab|exploit|malware|breach|cve|attack)\b/i,
  'Software': /\b(software|programming|code|developer|compiler|language|database|rust|python|javascript|typescript|golang|cargo|api)\b/i, 'Infrastructure': /\b(cloud|kubernetes|server|network|linux|infrastructure)\b/i,
  'Open Source': /\bopen.source\b/i, 'Privacy': /\bprivacy\b/i };
const tags = d.tags || (Object.keys(KW).filter(k => KW[k].test(title + ' ' + d.topic)).slice(0, 4));
if (!tags.length) tags.push('Technology');
const payload = { slug, title, date: today, excerpt, tags, readingTime: Math.max(1, Math.min(999, Math.ceil(d.wordCount / 200))),
  qualityScore: d.quality_score, content, sources: d.sources,
  editorNotes: { topic: d.topic, kind: d.kind, wordCount: d.wordCount, sectionCount: d.sectionCount, model: 'qwq:32b',
    writer: d.writer, editor: d.editorNote, linksRemoved: d.linksRemoved, issues: d.issues.map(i => i.type), generatedAt: d.timestamp } };
return [{ json: { payload, run: d.run, kind: d.kind, blockers: d.blockers, wouldPublish: d.wouldPublish } }];

const d = $input.first().json;
console.log('Agent 5: DRY RUN - publish to the blog API and the Telegram announcement were SKIPPED on purpose.');
console.log('Agent 5:', d.wouldPublish ? 'WOULD PUBLISH' : 'WOULD HOLD (not publish): ' + d.blockers.join('; '), '| slug', d.payload.slug, '| title:', d.payload.title, '| words:', d.payload.editorNotes.wordCount);
return [{ json: { dryRun: 'publish and Telegram announcement skipped', wouldPublish: d.wouldPublish, blockers: d.blockers,
  issues: d.payload.editorNotes.issues, slug: d.payload.slug, title: d.payload.title,
  excerpt: d.payload.excerpt, words: d.payload.editorNotes.wordCount, quality: d.payload.qualityScore, tags: d.payload.tags,
  sources: d.payload.sources.length, editor: d.payload.editorNotes.editor, contentPreview: d.payload.content.slice(0, 1500), run: d.run } }];

// Fix for 'publish never blocked': a post with blockers is HELD. Throwing sends one alert through the error workflow
// (which marks the run 'held' and, for a scheduled run, may try again later). The draft stays in this execution's data.
const d = $input.first().json;
if (d.blockers && d.blockers.length) throw new Error('Post held, not published: ' + d.blockers.join('; ').slice(0, 200));
return [{ json: d }];

function dayDone(run, rows, today) {
  run = run || {};
  const SLOT = ['scheduled', 'retry'];
  const dry = run.dryRun === true;
  const day = run.day || today;
  const same = (rows || []).filter(r => r && r.run_id && r.day === day && ((r.dry_run === true || r.dry_run === 'true') === dry));
  const own = same.find(r => r.run_id === run.runId);
  if (own && own.status === 'published')
    return { skip: true, reason: `run ${run.runId} was already published (${own.post_url || 'no url'})` };
  if (SLOT.includes(run.mode)) {
    const other = same.find(r => r.run_id !== run.runId && SLOT.includes(r.mode) && r.status === 'published');
    if (other) return { skip: true, reason: `the post for ${day} is already out (${other.post_url || other.run_id}, run ${other.run_id})` };
  }
  return { skip: false, reason: '' };
}

const g = $('Publish Gate').first().json;
const d = dayDone(g.run, $input.all().map(i => i.json), $now.setZone('UTC').toISODate());
if (d.skip) console.log('Agent 5: NOT publishing,', d.reason);
return [{ json: { ...g, skipPublish: d.skip, skipReason: d.reason } }];

const r = $input.first().json || {};
const prep = $('Convert MD to HTML & Prep Payload').first().json;
const slug = (r.post && r.post.slug) || null;
if (!slug) throw new Error('Blog API did not confirm the post: ' + JSON.stringify(r).slice(0, 200));
const url = `https://your-blog.example/blog/${slug}`;
console.log('Agent 5: published', url, r.updated ? '(UPDATED existing slug)' : '(new)');
return [{ json: { slug, url, title: prep.payload.title, excerpt: prep.payload.excerpt, run: prep.run, kind: prep.kind,
  wordCount: prep.payload.editorNotes.wordCount, qualityScore: prep.payload.qualityScore, readingTime: prep.payload.readingTime } }];

const p = $('Check Publish Response').first().json;
const head = p.kind === 'digest' ? 'Weekly digest published' : 'New post published';
const text = `${head}: ${p.title}

${p.excerpt}

${p.wordCount} words, about ${p.readingTime} min.
${p.url}
(The page goes live at the next site rebuild, within 6 hours.)`;
return [{ json: { text } }];

const d = $('Validate Quality').first().json, p = $('Check Publish Response').first().json;
return d.issues.map(i => ({ json: { issue_type: i.type, severity: i.severity, message: i.message, topic: d.topic, word_count: d.wordCount,
  quality_score: d.quality_score, timestamp: d.timestamp, post_title: p.title } }));

const d = $('Validate Quality').first().json;
const cats = ['AI', 'security', 'crypto', 'automation', 'infrastructure', 'software'];
const category = cats.find(c => String(d.topic).toLowerCase().includes(c.toLowerCase())) || 'tech';
return [{ json: { category, quality_score: d.quality_score, retry_count: 0, timestamp: d.timestamp } }];

const d = $('Validate Quality').first().json;
const seen = new Set();
return d.sources.map(s => (String(s.url).match(/^https?:\/\/([^\/]+)/) || [])[1]).filter(x => x && !seen.has(x) && seen.add(x))
  .map(domain => ({ json: { domain, quality_score: d.quality_score, timestamp: d.timestamp } }));
